// Referencia Capital — Feature pack V2
// Completes Auditoria de Leads, Creative Funnel Intelligence and Calculadora de Meta.

const V2 = {
  auditRange: '30',
  auditSearch: '',
  auditFilter: 'all',
  auditOpenDays: new Set(),
  funnelKey: 'all',
  funnelRank: 'sales',
  libraryPeriod: 'global',
  library: {campaign:'all',adset:'all',status:'all',format:'all',page:'all',maturity:'all'},
  expanded: {creative:false,sdr:false,closer:false},
  limits: {creative:3,sdr:3,closer:3},
  disabled: {creative:new Set(),sdr:new Set(),closer:new Set()},
  calculator: {month: new Date().toISOString().slice(0,7), baselinePeriod:'6m', baselineView:'daily'},
  history: null, historyLoading: null
};

function escV2(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function nV2(v){return new Intl.NumberFormat('pt-BR',{maximumFractionDigits:0}).format(Number(v||0))}
function mV2(v,decimals=0){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:decimals,maximumFractionDigits:decimals}).format(Number(v||0))}
function pV2(v,d=1){return new Intl.NumberFormat('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(v||0))+'%'}
function ratioV2(n,d){return d?100*Number(n||0)/Number(d||0):0}
function datePtV2(s){if(!s)return '—';const d=new Date(s+'T12:00:00');return d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.','').toUpperCase()}
function daysBetweenV2(a,b){const x=new Date(a+'T12:00:00'),y=new Date(b+'T12:00:00');return Math.max(1,Math.round((y-x)/86400000)+1)}

async function loadHistoryV2(days=190){if(V2.historyLoading)return V2.historyLoading;const until=document.querySelector('#until')?.value||new Date().toISOString().slice(0,10),d=new Date(until+'T12:00:00');d.setDate(d.getDate()-days+1);const since=d.toISOString().slice(0,10);V2.historyLoading=(window.historyHybridFetch?window.historyHybridFetch(since,until):api(`/api/history?since=${since}&until=${until}`)).then(j=>{V2.history=j;return j}).catch(()=>null).finally(()=>{V2.historyLoading=null});return V2.historyLoading}
function historyMapsV2(){const mm={},cm={};(V2.history?.metaDaily||[]).forEach(r=>mm[r.day]={...r,leads:Number(r.leads||0),spend:Number(r.spend||0),clicks:Number(r.clicks||0),lpv:Number(r.lpv||0),impressions:Number(r.impressions||0)});(V2.history?.crmDaily||[]).forEach(r=>cm[r.day]={...r,opportunities:Number(r.opportunities||0),meetings:Number(r.meetings||0),noShows:Number(r.no_shows??r.noShows??0),wins:Number(r.wins||0),revenue:Number(r.revenue||0)});return{mm,cm}}

// ---------- AUDITORIA ----------
function buildAuditDataset(){const {mm,cm}=historyMapsV2(),metaDaily={},crmDaily={};if(Object.keys(mm).length){Object.entries(mm).forEach(([d,r])=>metaDaily[d]=Number(r.leads||0));Object.entries(cm).forEach(([d,r])=>crmDaily[d]=Number(r.opportunities||0))}else{(state.daily||[]).forEach(r=>{const d=r.date_start||r.date_stop;if(d)metaDaily[d]=(metaDaily[d]||0)+Number(r.leads||0)})}const dates=[...new Set([...Object.keys(metaDaily),...Object.keys(crmDaily)])].sort(),metaTotal=dates.reduce((a,d)=>a+(metaDaily[d]||0),0),crmTotal=dates.reduce((a,d)=>a+(crmDaily[d]||0),0);return{dates,metaDaily,crmDaily,metaTotal,crmTotal}}

function auditCard(label,meta,crm,current=false){
  const hasCrm=Number.isFinite(crm); const diff=hasCrm?Math.abs(meta-crm):null; const ok=hasCrm&&diff===0;
  return `<article class="audit-summary-card ${current?'current':''}"><div class="audit-summary-label">${label}</div><div class="audit-summary-pair"><div><span>META</span><strong>${nV2(meta)}</strong></div><i></i><div><span>CRM</span><strong>${hasCrm?nV2(crm):'—'}</strong></div></div><div class="audit-summary-result ${ok?'ok':hasCrm?'warn':'neutral'}">${ok?'✓ Sem diferença':hasCrm?`Diferença: ${nV2(diff)}`:'CRM diário indisponível'}</div></article>`;
}

function renderAuditV2(){
  const root=document.querySelector('#page-audit'); if(!root)return;
  const ds=buildAuditDataset(); const dates=ds.dates; const last=dates.at(-1), yesterday=dates.at(-2);
  const last7=dates.slice(-7).reduce((s,d)=>s+(ds.metaDaily[d]||0),0);
  const last30=dates.slice(-30).reduce((s,d)=>s+(ds.metaDaily[d]||0),0);
  const cards=document.querySelector('#auditCards');
  if(cards) cards.innerHTML=[
    auditCard('ÚLTIMOS 30 DIAS',last30,dates.slice(-30).some(d=>d in ds.crmDaily)?dates.slice(-30).reduce((s,d)=>s+(ds.crmDaily[d]||0),0):NaN),
    auditCard('ÚLTIMOS 7 DIAS',last7,dates.slice(-7).some(d=>d in ds.crmDaily)?dates.slice(-7).reduce((s,d)=>s+(ds.crmDaily[d]||0),0):NaN),
    auditCard('ONTEM',yesterday?ds.metaDaily[yesterday]||0:0,yesterday&&yesterday in ds.crmDaily?ds.crmDaily[yesterday]:NaN),
    auditCard('HOJE',last?ds.metaDaily[last]||0:0,last&&last in ds.crmDaily?ds.crmDaily[last]:NaN,true)
  ].join('');
  renderAuditTimelineV2(ds);
  renderAuditDaysV2(ds);
}

function auditRangeDatesV2(ds){
  const all=ds.dates; if(V2.auditRange==='custom'){
    const a=document.querySelector('#auditFrom')?.value,b=document.querySelector('#auditTo')?.value;
    return all.filter(d=>(!a||d>=a)&&(!b||d<=b));
  }
  const n=Number(V2.auditRange)||30; return all.slice(-n);
}

function renderAuditTimelineV2(ds){
  const holder=document.querySelector('#auditChart'); if(!holder)return; const dates=auditRangeDatesV2(ds);
  if(!dates.length){holder.innerHTML='<div class="audit-state">Sem dados da Meta para o período selecionado.</div>';return}
  const vals=dates.map(d=>ds.metaDaily[d]||0),crmVals=dates.map(d=>d in ds.crmDaily?ds.crmDaily[d]:null), max=Math.max(...vals,...crmVals.filter(Number.isFinite),1), W=1200,H=230,L=42,R=18,T=22,B=34;
  const x=i=>L+i*(W-L-R)/Math.max(1,dates.length-1),y=v=>H-B-v/max*(H-T-B);
  const pts=vals.map((v,i)=>[x(i),y(v)]);
  // cubic smooth path using midpoint quadratic interpolation
  let path=`M ${pts[0][0]} ${pts[0][1]}`; for(let i=1;i<pts.length;i++){const p0=pts[i-1],p1=pts[i],mx=(p0[0]+p1[0])/2;path+=` C ${mx} ${p0[1]}, ${mx} ${p1[1]}, ${p1[0]} ${p1[1]}`}
  const markers=pts.map((p,i)=>`<g><circle cx="${p[0]}" cy="${p[1]}" r="4" class="audit-meta-point"><title>${datePtV2(dates[i])}: Meta ${nV2(vals[i])}</title></circle></g>`).join('');const crmPts=crmVals.map((v,i)=>Number.isFinite(v)?[x(i),y(v)]:null),validCrm=crmPts.filter(Boolean);let crmPath='';if(validCrm.length){crmPath=`M ${validCrm[0][0]} ${validCrm[0][1]}`;for(let i=1;i<validCrm.length;i++){const p0=validCrm[i-1],p1=validCrm[i],mx=(p0[0]+p1[0])/2;crmPath+=` C ${mx} ${p0[1]}, ${mx} ${p1[1]}, ${p1[0]} ${p1[1]}`}}
  const grids=[0,.25,.5,.75,1].map(k=>`<line x1="${L}" y1="${T+(H-T-B)*k}" x2="${W-R}" y2="${T+(H-T-B)*k}"/>`).join('');
  const labels=dates.map((d,i)=>i%(Math.ceil(dates.length/6))===0||i===dates.length-1?`<text x="${x(i)}" y="${H-8}" text-anchor="middle">${datePtV2(d)}</text>`:'').join('');
  holder.innerHTML=`<div class="audit-chart-toolbar"><div class="audit-chart-title"><strong>Auditoria Meta × CRM</strong><span>Compare volume de leads da Meta com entradas do CRM no mesmo dia.</span></div><div class="audit-period-tabs"><button data-ar="7" class="${V2.auditRange==='7'?'active':''}">7 dias</button><button data-ar="30" class="${V2.auditRange==='30'?'active':''}">30 dias</button><button data-ar="90" class="${V2.auditRange==='90'?'active':''}">90 dias</button><button data-ar="custom" class="${V2.auditRange==='custom'?'active':''}">Personalizado</button></div><div class="audit-custom hidden"><input id="auditFrom" type="date"><span>→</span><input id="auditTo" type="date"></div></div><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" class="audit-smooth-chart"><g class="grid">${grids}</g><path d="${path}" class="meta-line"/>${crmPath?`<path d="${crmPath}" class="crm-line"/>`:''}${markers}<g class="xlabels">${labels}</g></svg><div class="audit-chart-foot"><span><i class="legend-dot meta"></i>Meta</span><span class="${validCrm.length?'':'disabled-source'}"><i class="legend-dot crm"></i>${validCrm.length?'CRM':'CRM diário pendente'}</span></div>`;
  holder.querySelectorAll('[data-ar]').forEach(btn=>btn.onclick=()=>{V2.auditRange=btn.dataset.ar;holder.querySelectorAll('[data-ar]').forEach(x=>x.classList.toggle('active',x===btn));holder.querySelector('.audit-custom').classList.toggle('hidden',V2.auditRange!=='custom');renderAuditTimelineV2(ds)});
  if(V2.auditRange==='custom') holder.querySelector('.audit-custom')?.classList.remove('hidden');
}

