function auditSourceRowsV2(day,metaCount){const real=(state.crm?.auditLeads||[]).filter(x=>String(x.createdAt||'').slice(0,10)===day).map(x=>({...x,demo:false,campaign:x.campaign||x.utmCampaign||'Sem campanha',stage:x.stage||'Sem etapa',origin:x.origin||'PipeRun',source:x.source||'',medium:x.medium||'',utmCampaign:x.utmCampaign||x.campaign||'',utmContent:x.utmContent||'',metaId:x.metaId||'—',crmId:x.crmId||'—',match:x.match||'CRM persistido'}));return real.length?real:mockAuditLeadsV2(day,metaCount)}
function leadAuditStateV2(l){if(l.meta&&l.crm)return'ok';if(l.meta&&!l.crm)return'meta-only';if(!l.meta&&l.crm)return'crm-only';return'none'}
function auditRowsV2(day,metaCount){let rows=auditSourceRowsV2(day,metaCount);const f=V2.auditFilter,q=V2.auditSearch.toLowerCase().trim();rows=rows.filter(l=>{const st=leadAuditStateV2(l);const filter=f==='all'||(f==='diff'&&st!=='ok')||(f==='meta-only'&&st==='meta-only')||(f==='crm-only'&&st==='crm-only');const search=!q||[l.name,l.email,l.phone,l.campaign].join(' ').toLowerCase().includes(q);return filter&&search});return rows}
function auditLeadRowV2(l,i){const st=leadAuditStateV2(l),diff=st!=='ok',crmAction=l.crmUrl?`<button class="open-crm-real" data-url="${escV2(l.crmUrl)}" type="button">Abrir no CRM ↗</button>`:(l.crm?'<button class="open-crm-demo" type="button">Abrir no CRM ↗</button>':'');return `<div class="audit-lead-row ${diff?'has-diff':''}" data-lead-index="${i}"><div class="audit-lead-name" title="${escV2(l.name)}">${escV2(l.name)}</div><div class="audit-secondary email" title="${escV2(l.email)}">${escV2(l.email||'—')}</div><div class="audit-secondary phone">${escV2(l.phone||'—')}</div><div class="audit-campaign" title="${escV2(l.campaign)}">${escV2(l.campaign||'Sem campanha')}</div><div><span class="stage-chip">● ${escV2(l.stage||'Sem etapa')}</span></div><div class="audit-badges"><span class="micro-badge ${l.meta?'ok':'off'}">META ${l.meta?'✓':'✕'}</span><span class="micro-badge ${l.crm?'ok':'bad'}">CRM ${l.crm?'✓':'✕'}</span></div><button class="lead-more" aria-label="Ver mais">›</button><div class="audit-lead-detail"><div><label>Campanha completa</label><span>${escV2(l.campaign||'—')}</span></div><div><label>Origem</label><span>${escV2(l.origin||'—')}</span></div><div><label>UTM Source</label><span>${escV2(l.source||'—')}</span></div><div><label>UTM Medium</label><span>${escV2(l.medium||'—')}</span></div><div><label>UTM Campaign</label><span>${escV2(l.utmCampaign||'—')}</span></div><div><label>UTM Content</label><span>${escV2(l.utmContent||'—')}</span></div><div><label>Meta Lead ID</label><span>${escV2(l.metaId||'—')}</span></div><div><label>CRM ID</label><span>${escV2(l.crmId||'—')}</span></div><div><label>Criado em</label><span>${escV2(l.createdAt||'—')}</span></div><div><label>Correspondência</label><span>${escV2(l.match||'—')}</span></div><div class="detail-actions"><span class="demo-warning">${l.demo?'Dados demonstrativos enquanto não existe registro individual conciliável.':'Registro individual persistido do PipeRun; a marcação Meta usa Meta Lead ID ou ad_id quando disponível.'}</span>${crmAction}</div></div></div>`}
function renderAuditDaysV2(ds){const root=document.querySelector('#auditDays');if(!root)return;const dates=auditRangeDatesV2(ds).slice(-30).reverse();if(!dates.length){root.innerHTML='<div class="audit-state">Sem dias no período.</div>';return}if(!V2.auditOpenDays.size&&dates[0])V2.auditOpenDays.add(dates[0]);root.innerHTML=dates.map((d,idx)=>{const open=V2.auditOpenDays.has(d),meta=ds.metaDaily[d]||0,crm=d in ds.crmDaily?ds.crmDaily[d]:null,rows=auditSourceRowsV2(d,meta),rowsAreReal=rows.some(x=>!x.demo),rowDiff=rows.filter(x=>leadAuditStateV2(x)!=='ok').length,diff=crm==null?rowDiff:Math.abs(meta-crm),mo=rows.filter(x=>leadAuditStateV2(x)==='meta-only').length,co=rows.filter(x=>leadAuditStateV2(x)==='crm-only').length,unresolved=Math.max(0,meta-(crm??meta));return `<section class="audit-day-v2" data-day="${d}"><button class="audit-day-toggle"><span class="caret">${open?'▼':'▶'}</span><strong>${idx===0?'HOJE · ':''}${datePtV2(d)}</strong><span>Meta ${nV2(meta)}</span><span>CRM ${crm==null?'—':nV2(crm)}</span><i></i><span class="audit-pill ${diff?'warn':'ok'}">${crm==null?(rowDiff?`⚠ ${rowDiff} registros para revisar`:'✓ Sem diferença'):(diff?`⚠ ${diff} divergências`:'✓ Sem diferença')}</span></button><div class="audit-day-body ${open?'':'hidden'}"><div class="audit-tools"><div class="audit-filterbar"><button data-af="all" class="${V2.auditFilter==='all'?'active':''}">Todos ${rows.length}</button><button data-af="diff" class="${V2.auditFilter==='diff'?'active':''}">Divergências ${rowDiff}</button><button data-af="meta-only" class="${V2.auditFilter==='meta-only'?'active':''}">Meta sem CRM ${mo}</button><button data-af="crm-only" class="${V2.auditFilter==='crm-only'?'active':''}">CRM sem Meta ${co}</button></div><input class="audit-search" placeholder="Buscar lead..." value="${escV2(V2.auditSearch)}"></div>${unresolved>0&&rowsAreReal?`<div class="audit-coverage-note">A Meta registra ${nV2(unresolved)} lead(s) a mais neste dia. Para identificar nomes individuais desses registros, a origem precisa expor Meta Lead ID/Lead Ads; a diferença de volume continua sendo real e auditada.</div>`:''}<div class="audit-table-head"><span>LEAD</span><span>E-MAIL</span><span>TELEFONE</span><span>CAMPANHA</span><span>ETAPA</span><span>AUDITORIA</span><span>AÇÃO</span></div><div class="audit-leads">${auditRowsV2(d,meta).map(auditLeadRowV2).join('')||'<div class="audit-state">Nenhum resultado encontrado.</div>'}</div></div></section>`}).join('');root.querySelectorAll('.audit-day-toggle').forEach(b=>b.onclick=()=>{const day=b.closest('[data-day]').dataset.day;V2.auditOpenDays.has(day)?V2.auditOpenDays.delete(day):V2.auditOpenDays.add(day);renderAuditDaysV2(ds)});root.querySelectorAll('[data-af]').forEach(b=>b.onclick=()=>{V2.auditFilter=b.dataset.af;renderAuditDaysV2(ds)});root.querySelectorAll('.audit-search').forEach(i=>i.oninput=()=>{V2.auditSearch=i.value;renderAuditDaysV2(ds)});root.querySelectorAll('.lead-more').forEach(b=>b.onclick=()=>{const row=b.closest('.audit-lead-row');row.classList.toggle('expanded');b.textContent=row.classList.contains('expanded')?'⌄':'›'});root.querySelectorAll('.open-crm-real').forEach(b=>b.onclick=()=>window.open(b.dataset.url,'_blank','noopener'));root.querySelectorAll('.open-crm-demo').forEach(b=>b.onclick=()=>toast('Link direto ao CRM será ativado quando o CRM ID real estiver persistido.'))}


// ---------- FUNIL POR URL ----------
function extractCreativeUrlV2(c){
  if(!c)return''; const o=c.object_story_spec||{}, a=c.asset_feed_spec||{};
  return c.destination_url||c.object_url||o?.link_data?.link||o?.video_data?.call_to_action?.value?.link||a?.link_urls?.[0]?.website_url||'';
}
function normalizeUrlV2(u){try{const x=new URL(u);x.hash='';for(const k of [...x.searchParams.keys()]){const n=String(k).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(n.startsWith('utm_')||n==='fbclid'||n==='gclid'||/id.*(anuncio|conjunto|campanha)/i.test(n)||n.includes('{{'))x.searchParams.delete(k)}if(/^https?:$/.test(x.protocol))x.protocol='https:';const path=(x.pathname.replace(/\/+$/,'')||'/'),q=x.searchParams.toString();return x.origin+path+(q?'?'+q:'')}catch{return u||''}}
function funnelKeyFromAdV2(ad){const c=state.creativeMeta.get(String(ad.ad_id));const u=normalizeUrlV2(extractCreativeUrlV2(c));return u||'__sem_url__'}
function funnelNameV2(key,i=0){if(key==='__sem_url__')return'Sem URL identificada';try{const u=new URL(key),parts=u.pathname.split('/').filter(Boolean),host=u.hostname.replace(/^www\./,'').replace(/\.referenciacapital\.com\.br$/,'');const raw=parts.at(-1)||host;return raw.replace(/[-_]/g,' ').replace(/\b\w/g,c=>c.toUpperCase()).replace(/\bLp\b/g,'LP').replace(/\bClt\b/g,'CLT').replace(/\bBr\b/g,'BR')}catch{return`Funil ${i+1}`}}
function funnelGroupsV2(){const m=new Map();state.ads.forEach(ad=>{const k=funnelKeyFromAdV2(ad);if(!m.has(k))m.set(k,{key:k,ads:[],spend:0,leads:0,clicks:0,lpv:0,impressions:0});const g=m.get(k);g.ads.push(ad);['spend','leads','inline_link_clicks','lpv','impressions'].forEach(field=>{const target=field==='inline_link_clicks'?'clicks':field;g[target]+=Number(ad[field]||0)})});const arr=[...m.values()].sort((a,b)=>b.spend-a.spend);arr.forEach((g,i)=>g.name=funnelNameV2(g.key,i));return arr}
function selectedFunnelV2(){if(V2.funnelKey==='all')return{key:'all',name:'Todos os funis',ads:[...state.ads]};return funnelGroupsV2().find(x=>x.key===V2.funnelKey)||{key:'all',name:'Todos os funis',ads:[...state.ads]}}
function funnelTotalsV2(group){const ads=group.ads||[],spend=ads.reduce((a,x)=>a+Number(x.spend||0),0),leads=ads.reduce((a,x)=>a+Number(x.leads||0),0),clicks=ads.reduce((a,x)=>a+Number(x.inline_link_clicks||0),0),lpv=ads.reduce((a,x)=>a+Number(x.lpv||0),0),impressions=ads.reduce((a,x)=>a+Number(x.impressions||0),0);return{spend,leads,clicks,lpv,impressions}}
function crmAggregateForAdsV2(ads){let out={opportunities:0,meetings:0,noShows:0,wins:0,revenue:0};ads.forEach(ad=>{const c=crmFor(ad);if(c?.attributed){out.opportunities+=Number(c.opportunities||0);out.meetings+=Number(c.meetings||0);out.noShows+=Number(c.noShows||0);out.wins+=Number(c.wins||0);out.revenue+=Number(c.revenue||0)}});return out}

