function rankAdsV2(ads,rank=V2.funnelRank){return [...ads].sort((a,b)=>{const ca=crmFor(a),cb=crmFor(b),sa=creativeStats(a),sb=creativeStats(b),cost=(ad,c,k)=>Number(c[k]||0)?Number(ad.spend||0)/Number(c[k]):Infinity,roas=(ad,c)=>Number(ad.spend||0)?Number(c.revenue||0)/Number(ad.spend):0,hookScore=x=>.6*x.hook+.4*x.ret;switch(rank){case'sales':return Number(cb.wins||0)-Number(ca.wins||0)||b.leads-a.leads;case'revenue':return Number(cb.revenue||0)-Number(ca.revenue||0);case'meetings':return Number(cb.meetings||0)-Number(ca.meetings||0);case'leads':return b.leads-a.leads;case'hookscore':return hookScore(sb)-hookScore(sa);case'hook':return sb.hook-sa.hook;case'ctr':return sb.ctr-sa.ctr;case'cpc':return (Number(a.spend||0)/Math.max(Number(a.inline_link_clicks||0),1))-(Number(b.spend||0)/Math.max(Number(b.inline_link_clicks||0),1));case'cpl':return (sa.cpl||Infinity)-(sb.cpl||Infinity);case'cpr':return cost(a,ca,'meetings')-cost(b,cb,'meetings');case'cac':return cost(a,ca,'wins')-cost(b,cb,'wins');case'roas':return roas(b,cb)-roas(a,ca);case'spend':return b.spend-a.spend;default:return relevance(b).score-relevance(a).score}})}

function expandControlV2(type){return `<div class="rank-controls"><div class="rank-limits">${[3,5,10,999].map(n=>`<button data-limit-type="${type}" data-limit="${n}" class="${V2.limits[type]===n?'active':''}">${n===999?'Todos':'Top '+n}</button>`).join('')}</div><button class="expand-stage" data-expand-type="${type}">${V2.expanded[type]?'Recolher':'Expandir'}</button></div>`}
