function expandedStageV2(type,nodes){return `<div class="map-stage expanded-stage"><div class="node-group">${nodes.map((n,i)=>{if(type==='creative')return `<article class="element-node ${n.active?'':'disabled'}"><span class="rank-badge">#${i+1}</span><div class="element-preview">${n.preview?`<img src="${escV2(n.preview)}">`:'▶'}</div><strong title="${escV2(n.name)}">${escV2(n.name)}</strong><span>Hook ${pV2(n.hook)}</span><span>CTR ${pV2(n.ctr)}</span><span>${n.sales} vendas</span><label class="toggle-mini"><input type="checkbox" data-toggle-stage="creative" data-toggle-id="${n.id}" ${n.active?'checked':''}><i></i></label></article>`;if(type==='sdr')return `<article class="element-node person-node ${n.active?'':'disabled'}"><span class="rank-badge">#${i+1}</span><div class="person-avatar">${escV2(n.name.slice(0,1).toUpperCase())}</div><strong>${escV2(n.name)}</strong><span>${nV2(n.leads)} leads</span><span>${pV2(n.rate)} agenda</span><label class="toggle-mini"><input type="checkbox" data-toggle-stage="sdr" data-toggle-id="${n.id}" ${n.active?'checked':''}><i></i></label></article>`;return `<article class="element-node person-node ${n.active?'':'disabled'}"><span class="rank-badge">#${i+1}</span><div class="person-avatar">${escV2(n.name.slice(0,1).toUpperCase())}</div><strong>${escV2(n.name)}</strong><span>${nV2(n.opps)} oportunidades</span><span>${pV2(n.rate)} close</span><label class="toggle-mini"><input type="checkbox" data-toggle-stage="closer" data-toggle-id="${n.id}" ${n.active?'checked':''}><i></i></label></article>`}).join('')}</div>${expandControlV2(type)}</div>`}
