function renderMaturityV2(){const root=document.querySelector('#maturityContent');if(!root)return;const age=daysBetweenV2(document.querySelector('#since')?.value||iso(new Date()),document.querySelector('#until')?.value||iso(new Date())),phase=age>=14?'MADURO':age>=7?'MATURANDO':'MUITO CEDO';root.innerHTML=`<div class="maturity-cycle"><div class="small">CICLO OBSERVADO / JANELA</div><div class="big">${age} dias</div><div class="small">Status: <b>${phase}</b>. A leitura de venda, CAC e receita ganha confiança conforme a coorte amadurece.</div></div><div class="maturity-window"><b style="font-size:11px">Janela recomendada</b><div class="maturity-track"><div class="maturity-phase p1">0–2 dias<br>Aquisição</div><div class="maturity-phase p2">3–7 dias<br>Reuniões</div><div class="maturity-phase p3">8–14+ dias<br>Venda / CAC / Receita</div></div><div class="maturity-scale"><span>Dia 0</span><span>Dia 2</span><span>Dia 7</span><span>Dia 14+</span></div></div>`}
