function creativeFormatV2(ad){return Number(ad.views3||0)>0?'video':'image'}
function creativeMaturityV2(){return daysBetweenV2(document.querySelector('#since')?.value||iso(new Date()),document.querySelector('#until')?.value||iso(new Date()))>=14?'mature':'maturing'}
function aggregateCreativeRowsV2(ads){const fields=['spend','impressions','clicks','inline_link_clicks','outbound_clicks','leads','lpv','views3','v25','v50','v75','v95','v100','thru'];const m=new Map();for(const ad of ads){const id=creativeIdV2(ad);if(!m.has(id)){const row={...ad,_creativeId:id,_sourceAds:[]};for(const f of fields)row[f]=0;m.set(id,row)}const r=m.get(id);r._sourceAds.push(ad);for(const f of fields)r[f]+=Number(ad[f]||0)}return[...m.values()]}
