function hookScoreV2(row){const s=creativeStats(row);return Math.round(clamp(.6*s.hook+.4*s.ret,0,100))}
function relevanceRowV2(row){const src=row._sourceAds||[row];if(src.length===1)return relevance(src[0]).score;const spend=src.reduce((a,x)=>a+Number(x.spend||0),0);if(!spend)return Math.round(src.reduce((a,x)=>a+relevance(x).score,0)/Math.max(src.length,1));let score=src.reduce((a,x)=>a+relevance(x).score*Number(x.spend||0),0)/spend;const c=crmForRowV2(row);if(c.wins>0)score=Math.max(score,82);else if(row.leads===0&&spend>0)score=Math.min(score,30);return Math.round(clamp(score,0,100))}
