function uniqueOptionPairsV2(ads,idKey,nameKey){const m=new Map();for(const ad of ads){const id=String(ad[idKey]||ad[nameKey]||'').trim(),name=String(ad[nameKey]||ad[idKey]||'').trim();if(id&&!m.has(id))m.set(id,name)}return[...m.entries()].sort((a,b)=>a[1].localeCompare(b[1],'pt-BR'))}
