function creativeBreakdownV2(row){const all=state.ads.filter(ad=>creativeIdV2(ad)===row._creativeId),m=new Map();for(const ad of all){const k=funnelKeyFromAdV2(ad),g=m.get(k)||{name:funnelNameV2(k),ads:[],spend:0,leads:0,wins:0,revenue:0};g.ads.push(ad);g.spend+=Number(ad.spend||0);g.leads+=Number(ad.leads||0);const c=crmFor(ad);g.wins+=Number(c.wins||0);g.revenue+=Number(c.revenue||0);m.set(k,g)}return[...m.values()].sort((a,b)=>b.revenue-a.revenue||b.wins-a.wins||b.spend-a.spend)}
