function calcProjectionStateV2(){const root=document.querySelector('#page-calculator'),get=(id,def)=>Number(root.querySelector('#'+id)?.value??def)||0;const invest=get('calcInvest',30000),cpl=Math.max(get('calcCpl',30),.01),manual=root.querySelector('#calcLeadMode')?.value==='manual',leads=manual?get('calcManualLeads',1000):invest/cpl,txAg=get('calcTxAg',30)/100,txComp=get('calcTxComp',80)/100,txProp=get('calcTxProp',40)/100,txVenda=get('calcTxVenda',30)/100,ticket=get('calcTicket',100000),ag=leads*txAg,comp=ag*txComp,prop=comp*txProp,sales=prop*txVenda,revenue=sales*ticket;return{invest,cpl,leads,txAg,txComp,txProp,txVenda,ticket,ag,comp,prop,sales,revenue,manual}}
