function calcRenderCompareV2(p){const b=calcBaselineV2(),rows=[['Investimento',b.investimento,p.invest,'money',true],['CPL',b.cpl,p.cpl,'money2',true],['Leads',b.leads,p.leads,'num',true],['Agendamentos',b.ag,p.ag,'num',true],['Comparecimentos',b.comp,p.comp,'num',true],['Propostas',b.prop,p.prop,'num',!!b.propAvailable],['Vendas',b.vendas,p.sales,'num',true],['Ticket Médio',b.ticket,p.ticket,'money',true],['Receita',b.receita,p.revenue,'money',true]];document.querySelector('#calcCompareBody').innerHTML=rows.map(([label,bv,pv,type,available])=>{const fmt=type==='money'?x=>mV2(x):type==='money2'?x=>mV2(x,2):x=>nV2(x);if(!available)return `<tr><td><strong>${label}</strong></td><td>—</td><td>${fmt(pv)}</td><td title="Configure o estágio de proposta no CRM">aguardando CRM</td></tr>`;const d=pv-bv;return `<tr><td><strong>${label}</strong></td><td>${fmt(bv)}</td><td>${fmt(pv)}</td><td class="${d>=0?'positive':'negative'}">${d>=0?'+':''}${fmt(d)}</td></tr>`}).join('')}
function calcRenderDailyV2(){const tb=document.querySelector('#calcDailyBody');if(!tb)return;const days=(state.daily||[]).slice().sort((a,b)=>String(a.date_start).localeCompare(String(b.date_start))).slice(-31);const c=crmSummary(),totalMeta=days.reduce((a,x)=>a+Number(x.leads||0),0);tb.innerHTML=days.map(d=>{const leads=Number(d.leads||0),share=totalMeta?leads/totalMeta:0;return `<tr><td>${datePtV2(d.date_start||d.date_stop)}</td><td>${mV2(d.spend)}</td><td>${nV2(leads)}</td><td>${state.config.pipeRunTokenSet?'—':'—'}</td><td>—</td><td>—</td><td>—</td><td>—</td></tr>`}).join('')||'<tr><td colspan="8"><div class="audit-state">Sem dados diários para o período.</div></td></tr>'}


function svgIconV2(name){const p={spend:'<path d="M4 8h16M6 4h12v16H6zM9 12h6M9 16h4"/>',leads:'<circle cx="9" cy="8" r="3"/><circle cx="17" cy="10" r="2.5"/><path d="M3.5 20c.5-4 2.7-6 5.5-6s5 2 5.5 6M14 15c2.7.2 4.5 1.8 5 5"/>',cpl:'<circle cx="12" cy="12" r="8"/><path d="M12 7v10M15 9.5c-.7-1-1.7-1.5-3-1.5-1.8 0-3 1-3 2.3 0 3.7 6 1.7 6 5 0 1.5-1.3 2.7-3.2 2.7-1.4 0-2.6-.6-3.3-1.7"/>',lpv:'<path d="M4 5h16v14H4zM4 9h16M8 13h8M8 16h5"/>',meeting:'<rect x="4" y="5" width="16" height="15" rx="2"/><path d="M8 3v4M16 3v4M7 11h10M7 15h6"/>',sales:'<path d="M4 18l5-5 4 3 7-8M15 8h5v5"/><path d="M4 21h16"/>',impressions:'<path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6S2.5 12 2.5 12z"/><circle cx="12" cy="12" r="2.5"/>',clicks:'<path d="M7 3l10 8-5 1 3 6-3 1-3-6-4 4z"/>',funnel:'<path d="M4 5h16l-6 7v5l-4 2v-7z"/>',audit:'<path d="M5 4h14v16H5zM8 8h8M8 12h5M8 16h4"/><path d="M15 15l1.5 1.5L20 13"/>',calculator:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 11h2M12 11h2M16 11h.01M8 15h2M12 15h2M16 15h.01"/>',overview:'<path d="M4 13h6V4H4zM14 20h6V11h-6zM4 20h6v-4H4zM14 8h6V4h-6z"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${p[name]||p.overview}</svg>`}
function renderTrendSmoothV2(){const c=document.querySelector('#trendCanvas');if(!c)return;const ctx=c.getContext('2d'),metric=document.querySelector('#trendMetric')?.value||'leads',groups={};(state.daily||[]).forEach(r=>{const d=r.date_start||r.date_stop;if(!d)return;if(!groups[d])groups[d]={leads:0,spend:0,clicks:0};groups[d].leads+=Number(r.leads||0);groups[d].spend+=Number(r.spend||0);groups[d].clicks+=Number(r.inline_link_clicks||r.clicks||0)});const dates=Object.keys(groups).sort(),vals=dates.map(d=>groups[d][metric]||0),W=c.width,H=c.height,P={l:52,r:24,t:24,b:38};ctx.clearRect(0,0,W,H);const max=Math.max(...vals,1);ctx.strokeStyle='rgba(220,235,229,.075)';ctx.lineWidth=1;ctx.fillStyle='#78958b';ctx.font='11px Segoe UI';for(let i=0;i<5;i++){const y=P.t+(H-P.t-P.b)*i/4;ctx.beginPath();ctx.moveTo(P.l,y);ctx.lineTo(W-P.r,y);ctx.stroke();const v=max*(4-i)/4;ctx.fillText(metric==='spend'?mV2(v):nV2(v),4,y+4)}if(!dates.length){ctx.fillText('Sem dados no período.',P.l+20,H/2);return}const step=(W-P.l-P.r)/Math.max(dates.length-1,1),pts=vals.map((v,i)=>[P.l+i*step,H-P.b-(H-P.t-P.b)*(v/max)]);ctx.strokeStyle='#e8c46c';ctx.lineWidth=3;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(...pts[0]);for(let i=1;i<pts.length;i++){const [x0,y0]=pts[i-1],[x1,y1]=pts[i],mx=(x0+x1)/2;ctx.bezierCurveTo(mx,y0,mx,y1,x1,y1)}ctx.stroke();ctx.fillStyle='rgba(81,212,156,.11)';for(const [x,y] of pts){ctx.beginPath();ctx.arc(x,y,3.3,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#78958b';const every=Math.max(1,Math.ceil(dates.length/6));dates.forEach((d,i)=>{if(i%every===0||i===dates.length-1)ctx.fillText(d.slice(5).split('-').reverse().join('/'),pts[i][0]-14,H-12)})}

// ---------- GLOBAL PATCHES ----------
function enhanceOverviewV2(){const title=document.querySelector('.funnel-panel .panel-head h2');if(title)title.innerHTML='<span class="title-icon-v2">'+svgIconV2('funnel')+'</span> Desempenho do Funil';document.querySelectorAll('.nav-btn').forEach(b=>{const page=b.dataset.page,span=b.querySelector('span');if(page&&span&&!b.querySelector('svg'))b.innerHTML=`<i class="nav-icon-v2">${svgIconV2(page==='overview'?'overview':page==='audit'?'audit':page==='funnel'?'funnel':'calculator')}</i><span>${span.textContent}</span>`});const k=['spend','leads','cpl','lpv','meeting','sales'];document.querySelectorAll('.kpi-icon').forEach((el,i)=>el.innerHTML=svgIconV2(k[i]||'overview'));const f=['impressions','clicks','lpv','leads','meeting','sales'];document.querySelectorAll('.f-icon').forEach((el,i)=>el.innerHTML=svgIconV2(f[i]||'overview'));renderTrendSmoothV2()}
function activateV2ForPage(page){if(page==='audit'){renderAuditV2();loadHistoryV2(190).then(()=>renderAuditV2())}if(page==='funnel'){renderFunnelSelectorV2();renderFunnelMapV2();renderFunnelLibraryV2();const ids=[...new Set((state.ads||[]).map(a=>String(a.ad_id||'')).filter(Boolean))],withUrl=ids.filter(id=>extractCreativeUrlV2(state.creativeMeta.get(id))).length;if(ids.length&&withUrl/ids.length<.5&&typeof loadCreatives==='function'){loadCreatives(true).then(()=>{renderFunnelSelectorV2();renderFunnelMapV2();renderFunnelLibraryV2()}).catch(()=>{})}}if(page==='calculator'){renderCalculatorV2();loadHistoryV2(190).then(()=>renderCalculatorV2())}}

window.addEventListener('load',()=>{enhanceOverviewV2();loadHistoryV2(190).then(()=>{const active=document.querySelector('.page.active')?.id?.replace('page-','');if(active==='audit')renderAuditV2();if(active==='calculator')renderCalculatorV2()});document.querySelectorAll('.nav-btn').forEach(b=>b.addEventListener('click',()=>setTimeout(()=>activateV2ForPage(b.dataset.page),0)));const rf=document.querySelector('#refreshFunnelBtn');if(rf)rf.onclick=()=>{renderFunnelSelectorV2();renderFunnelMapV2();renderFunnelLibraryV2();toast('Leitura recalculada com a base salva.')};const active=document.querySelector('.page.active')?.id?.replace('page-','');if(active&&active!=='overview')activateV2ForPage(active)});
